import{_ as p,a0 as r,w as m,s as a,ao as l,I as n,a1 as e,A as s,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"初級：如何在 Linux Mint 上安裝 Google Chrome | LCTT x X-CMD","titleTemplate":false,"description":"初級：如何在 Linux Mint 上安裝 Google Chrome | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初級：如何在 Linux Mint 上安裝 Google Chrome | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初級：如何在 Linux Mint 上安裝 Google Chrome | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210803 How to Install Google Chrome on Linux Mint -Beginners Tip","title":"初級：如何在 Linux Mint 上安裝 Google Chrome","tag":"202108","desc":""},"relativePath":"202108/20210803 How to Install Google Chrome on Linux Mint -Beginners Tip.md","filePath":"[post].md"}'),g={name:"202108/20210803 How to Install Google Chrome on Linux Mint -Beginners Tip.md"};function u(d,o,h,f,C,x){const i=r("Link");return m(),a("div",null,[o[22]||(o[22]=l('<h1 id="初級-如何在-linux-mint-上安裝-google-chrome" tabindex="-1">初級：如何在 Linux Mint 上安裝 Google Chrome <a class="header-anchor" href="#初級-如何在-linux-mint-上安裝-google-chrome" aria-label="Permalink to “初級：如何在 Linux Mint 上安裝 Google Chrome”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202108/08/133301ni5k5i8rziezwe5i.jpg" alt=""></p><p>這應該是一個非常簡單的話題，但我寫這個是因為我看到很多網站推薦在 Linux Mint 上安裝 Google Chrome 的奇怪命令列步驟。那是可行的，但那是不必要的複雜，特別是對於不熟悉命令列的初學者。</p><p>實際上，你根本不需要走終端方式。你所要做的就是去谷歌瀏覽器的網站，下載 Ubuntu 的安裝文件並安裝。</p><p>讓我詳細介紹一下步驟，供你瞭解。</p><h3 id="在-linux-mint-上安裝-google-chrome" tabindex="-1">在 Linux Mint 上安裝 Google Chrome <a class="header-anchor" href="#在-linux-mint-上安裝-google-chrome" aria-label="Permalink to “在 Linux Mint 上安裝 Google Chrome”">​</a></h3><p>進入 Google Chrome 的網站。</p>',7)),n("p",null,[e(i,{href:"https://www.google.com/chrome/index.html"},{default:s(()=>[...o[0]||(o[0]=[t("Google Chrome Website",-1)])]),_:1})]),o[23]||(o[23]=n("p",null,"你會看到一個 “Download Chrome” 的按鈕。點擊它。",-1)),o[24]||(o[24]=n("p",null,[n("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/download-chrome-linux-mint.png?resize=800%2C320&ssl=1",alt:"Download Chrome for Linux"})],-1)),o[25]||(o[25]=n("p",null,"它將向你顯示在 Linux 上下載 Chrome 的兩個選項。選擇 Debian/Ubuntu 選項並點擊 “Accept and Install” 按鈕。",-1)),o[26]||(o[26]=n("p",null,[n("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/downloading-chrome-linux-mint.png?resize=800%2C679&ssl=1",alt:"Select Debian/Ubuntu option for Chrome package on Mint"})],-1)),n("p",null,[o[2]||(o[2]=t("在開始下載之前，Firefox 會詢問你是否要用 Gdebi 打開下載的文件或保存它。你可以選擇任何一個選項，因為最終你會 ",-1)),e(i,{href:"https://itsfoss.com/gdebi-default-ubuntu-software-center/"},{default:s(()=>[...o[1]||(o[1]=[t("使用 Gdebi 來安裝 deb 文件",-1)])]),_:1}),o[3]||(o[3]=t("。然而，我更喜歡先保存文件。",-1))]),o[27]||(o[27]=n("p",null,[n("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/saving-downloaded-chrome-linux-mint.png?resize=798%2C400&ssl=1",alt:"Save the deb file"})],-1)),o[28]||(o[28]=n("p",null,"等待下載完成。",-1)),o[29]||(o[29]=n("p",null,[n("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/finishing-chrome-download-linux-mint.png?resize=799%2C315&ssl=1",alt:"Wait for Google Chrome download to finish"})],-1)),n("p",null,[o[5]||(o[5]=t("下載完成後，在文件管理器中進入下載文件夾。要 ",-1)),e(i,{href:"https://itsfoss.com/install-deb-files-ubuntu/"},{default:s(()=>[...o[4]||(o[4]=[t("安裝 deb 文件",-1)])]),_:1}),o[6]||(o[6]=t("，可以雙擊它或者右擊它並選擇 “Open With GDebi Package Installer”。",-1))]),o[30]||(o[30]=l('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-google-chrome-deb-file-mint.png?resize=799%2C529&amp;ssl=1" alt="Double click on the downloaded deb file to install it"></p><p>等待幾秒鐘，它應該給你一個安裝的選項。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-google-chrome-gdebi-mint.png?resize=801%2C548&amp;ssl=1" alt="Hit the Install Package option in Gdebi"></p><p>它將要求你提供 Linux Mint 的賬户密碼。在 Linux 中，你需要提供你的密碼來安裝任何應用。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/enter-password-for-installing-chrome-mint.png?resize=800%2C399&amp;ssl=1" alt="Enter your password for installing an application"></p><p>你就要完成了。它將顯示哪些額外的軟件包將與之一起安裝（如果有的話）。點擊繼續按鈕即可。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-chrome-mint.png?resize=799%2C483&amp;ssl=1" alt="Details on the packages to be installed"></p><p>安裝完成應該只需要幾秒鐘或最多一分鐘。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/installing-chrome-mint-progress.png?resize=799%2C489&amp;ssl=1" alt="Installing Chrome in progress"></p><p>安裝完成後，你應該看到這樣的屏幕。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/chrome-installed-mint.png?resize=798%2C483&amp;ssl=1" alt="Chrome successfully installed on Linux Mint"></p><p>安裝完成後，你可以在應用菜單中尋找 Google Chrome 來運行它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/run-google-chrome-linux-mint.png?resize=798%2C580&amp;ssl=1" alt="Run Google Chrome in Linux Mint"></p><p>然後在 Linux Mint 上享受 Google Chrome。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/google-chrome-in-linux-mint-800x450.webp" alt="Google Chrome running in Linux Mint"></p><h3 id="如何在-linux-mint-上更新-google-chrome" tabindex="-1">如何在 Linux Mint 上更新 Google Chrome <a class="header-anchor" href="#如何在-linux-mint-上更新-google-chrome" aria-label="Permalink to “如何在 Linux Mint 上更新 Google Chrome”">​</a></h3><p>這個方法的好處是，谷歌瀏覽器會隨着系統的更新而更新。當你安裝 deb 文件的時候，它也會在你的系統中添加一個來自谷歌的倉庫。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/google-chrome-repo-added-mint.png?resize=799%2C272&amp;ssl=1" alt="Chrome adds a repository to the system for providing updates"></p><p>由於這個添加的倉庫，Chrome 瀏覽器上的更新將被添加到系統更新中。因此，當你更新 Linux Mint 時，它也會被更新（如果有可用的更新）。</p><h3 id="如何從-linux-mint-中刪除-google-chrome" tabindex="-1">如何從 Linux Mint 中刪除 Google Chrome <a class="header-anchor" href="#如何從-linux-mint-中刪除-google-chrome" aria-label="Permalink to “如何從 Linux Mint 中刪除 Google Chrome”">​</a></h3><p>不喜歡 Chrome？不用擔心。你可以從 Linux Mint 中卸載谷歌瀏覽器。同樣這次你也不需要使用終端。</p><p>點擊菜單，搜索 Chrome。在 Chrome 圖標上點擊右鍵，你會看到一個 “Uninstall” 選項。選擇它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/removing-google-chrome-from-mint.webp" alt="Removing Google Chrome from Linux Mint"></p><p>當然，你必須輸入你的密碼。它將顯示要刪除的軟件包。在這裏點擊 OK。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/uninstalling-google-chrome-from-linux-mint.webp" alt="Uninstalling Google Chrome from Linux mint"></p><p>你可以留下 Google Chrome 的倉庫，也可以刪除它。這是你的選擇。</p><p>我希望你覺得這個教程對在 Linux Mint 上使用 Google Chrome 有幫助。</p><hr>',28)),n("p",null,[o[8]||(o[8]=t("via: ",-1)),e(i,{href:"https://itsfoss.com/install-chrome-linux-mint/"},{default:s(()=>[...o[7]||(o[7]=[t("https://itsfoss.com/install-chrome-linux-mint/",-1)])]),_:1})]),n("p",null,[o[13]||(o[13]=t("作者：",-1)),e(i,{href:"https://itsfoss.com/author/abhishek/"},{default:s(()=>[...o[9]||(o[9]=[t("Abhishek Prakash",-1)])]),_:1}),o[14]||(o[14]=t(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...o[10]||(o[10]=[t("lujun9972",-1)])]),_:1}),o[15]||(o[15]=t(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:s(()=>[...o[11]||(o[11]=[t("geekpi",-1)])]),_:1}),o[16]||(o[16]=t(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...o[12]||(o[12]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[19]||(o[19]=t("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[17]||(o[17]=[t("LCTT",-1)])]),_:1}),o[20]||(o[20]=t(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:s(()=>[...o[18]||(o[18]=[t("Linux中國",-1)])]),_:1}),o[21]||(o[21]=t(" 榮譽推出",-1))])])}const G=p(g,[["render",u]]);export{L as __pageData,G as default};
